DIMENSIONS=[]
def dim(e,s,q,v,u='m',page='',caveat='',status='documented',method='Published explicit dimension or schedule',kind=''):
    scale={'ft':(.3048,'m'),'ft2':(.09290304,'m2'),'in':(.0254,'m'),'mm':(.001,'m')}
    factor,unit=scale.get(u,(1,u))
    DIMENSIONS.append(dict(example_id=e,source_id=s,quantity=q,value=v,units=u,
       metric_value=round(v*factor,8) if v is not None else '',metric_units=unit,
       evidence_status=status,evidence_kind=kind or ('game proposal' if status=='proposed' else 'published value'),
       method=method,sheet_page=page,caveat=caveat))
def sb(e,page,w,d,area,count):
    for q,v,u in [('main_width',w,'ft'),('main_depth',d,'ft'),('full_storeys',2,'storeys'),('finished_gross',area,'ft2'),('dwellings',count,'dwellings')]:
        dim(e,'US1',q,v,u,page,'Preapproved design, not as-built.',kind='design model')
